source:
DIF:EMA(CLOSE,4*MACDNUM(1))-EMA(CLOSE,4*MACDNUM(2));
DEA:EMA(DIF,4*MACDNUM(3));
MACD:(DIF-DEA)*2,COLORSTICK;

A1:=BARSLAST(REF(CROSS(DIF,DEA),1));
B1:=REF(C,A1+1)>C AND REF(DIF,A1+1)<DIF AND CROSS(DIF,DEA);
MACD底背离:=FILTER(B1>0,5);
DRAWICON(MACD底背离,DIF,1);

C1:=BARSLAST(REF(CROSS(DEA,DIF),1));
D1:=REF(C,C1+1)<C AND REF(DIF,C1+1)>DIF AND CROSS(DEA,DIF);
MACD顶背离:=FILTER(D1>0,5);
DRAWICON(MACD顶背离,DIF,2);

LC:=REF(CLOSE,1);
DIF:=CLOSE-IF(CLOSE>LC,MIN(LOW,LC),MAX(HIGH,LC));
ACD:SUM(IF(CLOSE=LC,0,DIF),0);
MAACD:EXPMEMA(ACD,M);

DIF:EMA(CLOSE,16*MACDNUM(1))-EMA(CLOSE,16*MACDNUM(2));
DEA:EMA(DIF,16*MACDNUM(3));
MACD:(DIF-DEA)*2,COLORSTICK;

A1:=BARSLAST(REF(CROSS(DIF,DEA),1));
B1:=REF(C,A1+1)>C AND REF(DIF,A1+1)<DIF AND CROSS(DIF,DEA);
MACD底背离:=FILTER(B1>0,5);
DRAWICON(MACD底背离,DIF,1);

C1:=BARSLAST(REF(CROSS(DEA,DIF),1));
D1:=REF(C,C1+1)<C AND REF(DIF,C1+1)>DIF AND CROSS(DEA,DIF);
MACD顶背离:=FILTER(D1>0,5);
DRAWICON(MACD顶背离,DIF,2);

DIF:EMA(CLOSE,MACDNUM(1))-EMA(CLOSE,MACDNUM(2));
DEA:EMA(DIF,MACDNUM(3));
MACD:(DIF-DEA)*2,COLORSTICK;

A1:=BARSLAST(REF(CROSS(DIF,DEA),1));
B1:=REF(C,A1+1)>C AND REF(DIF,A1+1)<DIF AND CROSS(DIF,DEA);
MACD底背离:=FILTER(B1>0,5);
DRAWICON(MACD底背离,DIF,1);

C1:=BARSLAST(REF(CROSS(DEA,DIF),1));
D1:=REF(C,C1+1)<C AND REF(DIF,C1+1)>DIF AND CROSS(DEA,DIF);
MACD顶背离:=FILTER(D1>0,5);
DRAWICON(MACD顶背离,DIF,2);

V1:=CHBI(H,L,P);
DRAWLINE(V1 =-1, L, V1 =1, H, 0)N'画笔' COLORRED, LINETHICK1;
DRAWLINE(V1 =1, H, V1 =-1, L, 0)N'画笔' COLORGREEN, LINETHICK1;
DRAWLINE(V1 =-1, L, V1 =2, H, 0)N'画笔' COLORRED, DOTLINE;
DRAWLINE(V1 =1, H, V1 =-2, L, 0)N'画笔' COLORGREEN, DOTLINE;

VAR4:=BIZHONGSHU(M);{参数M=1 中枢只画3段，M=2中枢延时部分全画出}

ZSG:=BIZHONGSHUG;
ZSD:=BIZHONGSHUD;
VAR5:=BIMMD(C);
VAR6:=BISMMD;

DRAWTRANSRECT(VAR4=1 AND ZSG>ZSD,ZSD,VAR4=2 AND ZSG>ZSD,ZSG,96)N'画中枢',COLORRED;
DRAWTRANSRECT(VAR4=3 AND ZSG >ZSD,ZSD,VAR4=4 AND ZSG>ZSD,ZSG,96)N'画中枢',COLORGREEN;
DRAWLINE(VAR4=1,(ZSG+ZSD)/2,VAR4=2,(ZSG+ZSD)/2,0)N'画中枢中轴',COLORWHITE,LINETHICK1,DOTLINE;
DRAWLINE(VAR4=3,(ZSG+ZSD)/2,VAR4=4,(ZSG+ZSD)/2,0)N'画中枢中轴',COLORWHITE,LINETHICK1,DOTLINE;

DRAWTEXT(VAR5=-1 ,HIGH,'一卖')N'一卖',COLORGREEN,LINETHICK1;
DRAWTEXT(VAR5=1 ,LOW,'一买')N'一买',COLORRED,LINETHICK1;
DRAWTEXT(VAR5=-2,HIGH,'二卖')N'二卖',COLORGREEN,LINETHICK1;
DRAWTEXT(VAR5=2,LOW,'二买')N'二买',COLORRED,LINETHICK1;
DRAWTEXT(VAR6=-1,HIGH,'三卖')N'三卖',COLORGREEN,LINETHICK1;
DRAWTEXT(VAR6=1 ,LOW,'三买')N'三买',COLORRED,LINETHICK1;

V1:=CHBI(H,L,P);
DRAWLINE(V1 =-1, L, V1 =1, H, 0)N'笔' COLORRED, LINETHICK1;
DRAWLINE(V1 =1, H, V1 =-1, L, 0)N'笔' COLORGREEN, LINETHICK1;
DRAWLINE(V1 =-1, L, V1 =2, H, 0)N'笔' COLORRED, DOTLINE;
DRAWLINE(V1 =1, H, V1 =-2, L, 0)N'笔' COLORGREEN, DOTLINE;
V2:=CHDUAN;
DRAWLINE(V2 =-1, L, V2 =1, H, 0)N'段'  COLORBLUE, LINETHICK2;
DRAWLINE(V2 =1, H, V2 =-1, L, 0)N'段'  COLORBLUE, LINETHICK2;
DRAWLINE(V2 =-1, L, BARSLAST(V2=-2)=0 AND V2 =2, H, 0)N'段'  COLORBLUE, DOTLINE;
DRAWLINE(V2 =1, H, BARSLAST(V2=2)=0 AND V2 =-2, L, 0)N'段'  COLORBLUE, DOTLINE;
DRAWLINE(V2 =-2, L, V2 =2, H, 0)N'段'  COLORBLUE, DOTLINE;
DRAWLINE(V2 =2, H, V2 =-2, L, 0)N'段'  COLORBLUE, DOTLINE;
VAR4:=DZHONGSHU(M) ;{处理中枢}
{参数M=1 中枢只画3段，M=2中枢延时部分全画出}
ZSG:=DZHONGSHUG;
ZSD:= DZHONGSHUD;
VAR5:=DUANMMD(C);
VAR6:=DUANSMMD;

DRAWTRANSRECT(VAR4=1 AND ZSG>ZSD,ZSD,VAR4=2 AND ZSG>ZSD,ZSG,96)N'中枢',COLORRED;
DRAWTRANSRECT(VAR4=3 AND ZSG >ZSD,ZSD,VAR4=4 AND ZSG>ZSD,ZSG,96)N'中枢',COLORBLUE;
DRAWLINE(VAR4=1,(ZSG+ZSD)/2,VAR4=2,(ZSG+ZSD)/2,0)N'中枢中轴',COLORWHITE,LINETHICK1,DOTLINE;
DRAWLINE(VAR4=3,(ZSG+ZSD)/2,VAR4=4,(ZSG+ZSD)/2,0)N'中枢中轴',COLORWHITE,LINETHICK1,DOTLINE;
DRAWTEXT(VAR5=-1 ,HIGH,'一卖')N'一卖',COLORGREEN,LINETHICK1;
DRAWTEXT(VAR5=1 ,LOW,'一买')N'一买',COLORRED,LINETHICK1;
DRAWTEXT(VAR5=-2,HIGH,'二卖')N'二卖',COLORGREEN,LINETHICK1;
DRAWTEXT(VAR5=2,LOW,'二买')N'二买',COLORRED,LINETHICK1;
DRAWTEXT(VAR6=-1,HIGH,'三卖')N'三卖',COLORGREEN,LINETHICK1;
DRAWTEXT(VAR6=1 ,LOW,'三买')N'三买',COLORRED,LINETHICK1;

CHDL:CHDLM(C,1),COLOR5454FF;
CHDDBS:=CHDLM(C,2);

DRAWICON(CHDDBS=-1,9,40);
DRAWICON(CHDDBS=1,65,4);
DRAWICON(CHDDBS=-2,17,1);
DRAWICON(CHDDBS=2,57,2);

V1:=CHBI(H,L,P);
DRAWLINE(V1 =-1, L, V1 =1, H, 0) COLORRED, LINETHICK1;
DRAWLINE(V1 =1, H, V1 =-1, L, 0) COLORGREEN, LINETHICK1;
DRAWLINE(V1 =-1, L, V1 =2, H, 0) COLORRED, DOTLINE;
DRAWLINE(V1 =1, H, V1 =-2, L, 0) COLORGREEN, DOTLINE;

T1:=STRCAT('底:', VAR2STR(L,DIGIT));
DRAWTEXT(V1 =-1, L, T1) COLORGREEN;
DRAWTEXT(V1 =1, H, STRCAT('顶:', VAR2STR(H,DIGIT))) COLORRED;

VAR1:=CHBI(H,L,P);
DRAWLINE(VAR1 =-1, L, VAR1 =1, H, 0) COLORRED, LINETHICK1;
DRAWLINE(VAR1 =1, H, VAR1 =-1, L, 0) COLORGREEN, LINETHICK1;
DRAWLINE(VAR1 =-1, L, VAR1 =2, H, 0) COLORRED, DOTLINE;
DRAWLINE(VAR1 =1, H, VAR1 =-2, L, 0) COLORGREEN, DOTLINE;

VAR2:=CHDUAN;

DRAWLINE(VAR2 =-1, L, VAR2 =1, H, 0) COLORBLUE, LINETHICK2;
DRAWLINE(VAR2 =1, H, VAR2 =-1, L, 0) COLORBLUE, LINETHICK2;
DRAWLINE(VAR2 =-1, L, VAR2 =2, H, 0) COLORBLUE, DOTLINE;
DRAWLINE(VAR2 =1, H, VAR2 =-2, L, 0) COLORBLUE, DOTLINE;

VAR3:=CHZSDG(VAR2);
DRAWLINE(VAR3=1,H,VAR3=-1,L,0),COLORRED,LINETHICK2;
DRAWLINE(VAR3=-1,L,VAR3=1,H,0),COLORRED,LINETHICK2;

VAR4:=CHNZSQJ;
ZSG:=BIZHONGSHUG;
ZSD:=BIZHONGSHUD;
DRAWTRANSRECT(VAR4=1 AND ZSG>ZSD ,ZSD,VAR4=2 AND ZSG>ZSD ,ZSG,96),COLORRED;
DRAWTRANSRECT(VAR4=3 AND ZSG >ZSD ,ZSD,VAR4=4 AND ZSG>ZSD ,ZSG,96),COLORGREEN;

VAR5:=CHZSDG(VAR3);

DRAWLINE(VAR5=1,H,VAR5=-1,L,0),COLORWHITE,LINETHICK2;
DRAWLINE(VAR5=-1,L,VAR5=1,H,0),COLORWHITE,LINETHICK2;

VAR6:=CHZSDG(VAR5);

DRAWLINE(VAR6=1,H,VAR6=-1,L,0),COLORGREEN,LINETHICK2;
DRAWLINE(VAR6=-1,L,VAR6=1,H,0),COLORGREEN,LINETHICK2;

VAR1:=CHBI(H,L,P);
DRAWLINE(VAR1 =-1, L, VAR1 =1, H, 0), COLORWHITE, LINETHICK1;
DRAWLINE(VAR1 =1, H, VAR1 =-1, L, 0) ,COLORWHITE, LINETHICK1;
DRAWLINE(VAR1 =-1, L, VAR1 =2, H, 0) COLORRED, DOTLINE;
DRAWLINE(VAR1 =1, H, VAR1 =-2, L, 0) COLORGREEN, DOTLINE;

VAR2:=CHZSDG(VAR1);
DRAWLINE(VAR2=1,H,VAR2=-1,L,0),COLORGREEN,LINETHICK2;
DRAWLINE(VAR2=-1,L,VAR2=1,H,0),COLORGREEN,LINETHICK2;
VAR3:=CHZSDG(VAR2);
DRAWLINE(VAR3=1,H,VAR3=-1,L,0),COLORRED,LINETHICK2;
DRAWLINE(VAR3=-1,L,VAR3=1,H,0),COLORRED,LINETHICK2;

DIF:=ADVANCE-DECLINE;
EMA1:=EMA(DIF,N1);
EMA2:=EMA(DIF,N2);
MCL:EMA1-EMA2;
MAMCL1:EMA1;
MAMCL2:EMA2;

LC:=REF(CLOSE,1);
RSI1:SMA(MAX(CLOSE-LC,0),N1,1)/SMA(ABS(CLOSE-LC),N1,1)*100;
RSI2:SMA(MAX(CLOSE-LC,0),N2,1)/SMA(ABS(CLOSE-LC),N2,1)*100;
RSI3:SMA(MAX(CLOSE-LC,0),N3,1)/SMA(ABS(CLOSE-LC),N3,1)*100;

RSV:=(CLOSE-LLV(LOW,N))/(HHV(HIGH,N)-LLV(LOW,N))*100;
K:SMA(RSV,M1,1);
D:SMA(K,M2,1);

LOWV:=LLV(LOW,N);
HIGHV:=HHV(HIGH,N);
RSV:=EMA((CLOSE-LOWV)/(HIGHV-LOWV)*100,M);
K:EMA(RSV,M);
D:MA(K,M);

RSV:= (HHV(HIGH,N)-CLOSE)/(HHV(HIGH,N)-LLV(LOW,N))*100;
LWR1:SMA(RSV,M1,1);
LWR2:SMA(LWR1,M2,1);

DIF:=CLOSE-REF(CLOSE,1);
VU:=IF(DIF>=0,DIF,0);
VD:=IF(DIF<0,-DIF,0);
MAU1:=MEMA(VU,M1);
MAD1:=MEMA(VD,M1);
MAU2:=MEMA(VU,M2);
MAD2:=MEMA(VD,M2);
RSI10:MA(100*MAU1/(MAU1+MAD1),M1);
RSI6:MA(100*MAU2/(MAU2+MAD2),M2);

BIAS1 :(CLOSE-MA(CLOSE,N1))/MA(CLOSE,N1)*100;
BIAS2 :(CLOSE-MA(CLOSE,N2))/MA(CLOSE,N2)*100;
BIAS3 :(CLOSE-MA(CLOSE,N3))/MA(CLOSE,N3)*100;

BIAS36:MA(CLOSE,3)-MA(CLOSE,6);
BIAS612:MA(CLOSE,6)-MA(CLOSE,12);
MABIAS:MA(BIAS36,M);

DTM:=IF(OPEN<=REF(OPEN,1),0,MAX((HIGH-OPEN),(OPEN-REF(OPEN,1))));
DBM:=IF(OPEN>=REF(OPEN,1),0,MAX((OPEN-LOW),(OPEN-REF(OPEN,1))));
STM:=SUM(DTM,N);
SBM:=SUM(DBM,N);
ADTM:IF(STM>SBM,(STM-SBM)/STM,IF(STM=SBM,0,(STM-SBM)/SBM));
MAADTM:MA(ADTM,M);

MID:=(3*CLOSE+LOW+OPEN+HIGH)/6;
DKX:(20*MID+19*REF(MID,1)+18*REF(MID,2)+17*REF(MID,3)+
16*REF(MID,4)+15*REF(MID,5)+14*REF(MID,6)+
13*REF(MID,7)+12*REF(MID,8)+11*REF(MID,9)+
10*REF(MID,10)+9*REF(MID,11)+8*REF(MID,12)+
7*REF(MID,13)+6*REF(MID,14)+5*REF(MID,15)+
4*REF(MID,16)+3*REF(MID,17)+2*REF(MID,18)+REF(MID,20))/210;
MADKX:MA(DKX,M);

MID:=SUM(VOL*(2*CLOSE-HIGH-LOW)/(HIGH+LOW),0);
CHO:MA(MID,N1)-MA(MID,N2);
MACHO:MA(CHO,M);

MTR:=SUM(MAX(MAX(HIGH-LOW,ABS(HIGH-REF(CLOSE,1))),ABS(REF(CLOSE,1)-LOW)),N);
HD :=HIGH-REF(HIGH,1);
LD :=REF(LOW,1)-LOW;
DMP:=SUM(IF(HD>0&&HD>LD,HD,0),N);
DMM:=SUM(IF(LD>0&&LD>HD,LD,0),N);
PDI: DMP*100/MTR;
MDI: DMM*100/MTR;
ADX: MA(ABS(MDI-PDI)/(MDI+PDI)*100,M);
ADXR:(ADX+REF(ADX,M))/2;

VOLUME:=MA(VOL,N)/VOL;
MID:=100*(HIGH+LOW-REF(HIGH+LOW,1))/(HIGH+LOW);
EMV:MA(MID*VOLUME*(HIGH-LOW)/MA(HIGH-LOW,N),N);
MAEMV:MA(EMV,M);

DIF:EMA(VOL,SHORT)-EMA(VOL,LONG);
DEA:EMA(DIF,MID);
MACD:DIF-DEA,COLORSTICK;

DIF:EMA(CLOSE,N1)-EMA(CLOSE,N2);
MACD:EMA(DIF,M);
DDIF:DIF-MACD;

MTR:=EMA(EMA(EMA(CLOSE,N),N),N);
TRIX:(MTR-REF(MTR,1))/REF(MTR,1)*100;
MATRIX:MA(TRIX,M) ;

TH:=MAX(HIGH,REF(CLOSE,1));
TL:=MIN(LOW,REF(CLOSE,1));
ACC1:=SUM(CLOSE-TL,N1)/SUM(TH-TL,N1);
ACC2:=SUM(CLOSE-TL,N2)/SUM(TH-TL,N2);
ACC3:=SUM(CLOSE-TL,N3)/SUM(TH-TL,N3);
UOS:(ACC1*N2*N3+ACC2*N1*N3+ACC3*N1*N2)*100/(N1*N2+N1*N3+N2*N3);
MAUOS:EXPMEMA(UOS,M);

ZS:(INDEXC-REF(INDEXC,N))/REF(INDEXC,N);
GG:(CLOSE-REF(CLOSE,N))/REF(CLOSE,N);
MADBQR1:MA(GG,M1);
MADBQR2:MA(GG,M2);
MADBQR3:MA(GG,M3);

JS:100*(CLOSE-REF(CLOSE,N))/(N*REF(CLOSE,N));
MAJS1:MA(JS,M1);
MAJS2:MA(JS,M2);
MAJS3:MA(JS,M3);

MAL:=MA(CLOSE,5);
MAS:=MA(MA(CLOSE,20),5);
CYEL:(MAL-REF(MAL,1))/REF(MAL,1)*100;
CYES:(MAS-REF(MAS,1))/REF(MAS,1)*100;

个股: (CLOSE-REF(CLOSE,N))/REF(CLOSE,N)*100; 
大盘: (INDEXC-REF(INDEXC,N))/REF(INDEXC,N)*100; 
强弱值:EMA(个股-大盘,2),COLORSTICK;

AA:=ABS((2*CLOSE+HIGH+LOW)/4-MA(CLOSE,N))/MA(CLOSE,N); 
轨道:DMA(CLOSE,AA);
压力线:(1+M/100)*轨道; 
支撑线:(1-M/100)*轨道;

VAR1:=(CLOSE-LLV(LOW,60))/(HHV(HIGH,60)-LLV(LOW,60))*80; 
B:SMA(VAR1,N,1); 
VAR2:SMA(B,M,1); 
绝路航标:IF(CROSS(B,VAR2) AND B<40,50,0);

MID:=REF(HIGH+LOW,1)/2;
CR:SUM(MAX(0,HIGH-MID),N)/SUM(MAX(0,MID-LOW),N)*100;
MA1:REF(MA(CR,M1),M1/2.5+1);
MA2:REF(MA(CR,M2),M2/2.5+1);
MA3:REF(MA(CR,M3),M3/2.5+1);
MA4:REF(MA(CR,M4),M4/2.5+1);

TH:=SUM(IF(CLOSE>REF(CLOSE,1),VOL,0),N);
TL:=SUM(IF(CLOSE<REF(CLOSE,1),VOL,0),N);
TQ:=SUM(IF(CLOSE=REF(CLOSE,1),VOL,0),N);
VR:100*(TH*2+TQ)/(TL*2+TQ);
MAVR:MA(VR,M);

MIDA:=CLOSE-MIN(REF(CLOSE,1),LOW);
MIDB:=IF(CLOSE<REF(CLOSE,1),CLOSE-MAX(REF(CLOSE,1),HIGH),0);
WAD:SUM(IF(CLOSE>REF(CLOSE,1),MIDA,MIDB),0);
MAWAD:MA(WAD,M);

DIVE:=0.01*EMA(AMOUNT,N)/EMA(VOL,N);
CYR:(DIVE/REF(DIVE,1)-1)*100;
MACYR:MA(CYR,M);

AMOW:AMOUNT/10000.0,VOLSTICK;
AMO1:MA(AMOW,M1);
AMO2:MA(AMOW,M2);

VA:=IF(CLOSE>REF(CLOSE,1),VOL,-VOL);
OBV:SUM(IF(CLOSE=REF(CLOSE,1),0,VA),0);
MAOBV:MA(OBV,M);

LC:=REF(VOL,1);
RSI1:SMA(MAX(VOL-LC,0),N1,1)/SMA(ABS(VOL-LC),N1,1)*100;
RSI2:SMA(MAX(VOL-LC,0),N2,1)/SMA(ABS(VOL-LC),N2,1)*100;
RSI3:SMA(MAX(VOL-LC,0),N3,1)/SMA(ABS(VOL-LC),N3,1)*100;

GG:=VOL/SUM(REF(VOL,1),N);
ZS:=INDEXV/SUM(REF(INDEXV,1),N);
DBLB:GG/ZS;
MADBLB:MA(DBLB,M);

MA1:MA(CLOSE,M1);
MA2:MA(CLOSE,M2);
MA3:MA(CLOSE,M3);
MA4:MA(CLOSE,M4);
MA5:MA(CLOSE,M5);
MA6:MA(CLOSE,M6);
MA7:MA(CLOSE,M7);
MA8:MA(CLOSE,M8);

DRAWKLINE(H,O,L,C);
EXP1:EMA(CLOSE,M1);
EXP2:EMA(CLOSE,M2);

HMA1:MA(HIGH,M1);
HMA2:MA(HIGH,M2);
HMA3:MA(HIGH,M3);
HMA4:MA(HIGH,M4);
HMA5:MA(HIGH,M5);

LMA1:MA(LOW,M1);
LMA2:MA(LOW,M2);
LMA3:MA(LOW,M3);
LMA4:MA(LOW,M4);
LMA5:MA(LOW,M5);

VV:=(HIGH+OPEN+LOW+CLOSE)/4;
VMA1:MA(VV,M1);
VMA2:MA(VV,M2);
VMA3:MA(VV,M3);
VMA4:MA(VV,M4);
VMA5:MA(VV,M5);

AMOV:=VOL*(OPEN+CLOSE)/2;
AMV1:SUM(AMOV,M1)/SUM(VOL,M1);
AMV2:SUM(AMOV,M2)/SUM(VOL,M2);
AMV3:SUM(AMOV,M3)/SUM(VOL,M3);
AMV4:SUM(AMOV,M4)/SUM(VOL,M4);

CV:=CLOSE;
BBIBOLL:(MA(CV,3)+MA(CV,6)+MA(CV,12)+MA(CV,24))/4;
UPR:BBIBOLL+M*STD(BBIBOLL,N);
DWN:BBIBOLL-M*STD(BBIBOLL,N);

NN:=(H+L)/2;
上唇:REF(MA(NN,5),3),COLOR40FF40;
牙齿:REF(MA(NN,8),5),COLOR0000C0;
下颚:REF(MA(NN,13),8),COLORFF4040;

BOLL:MA(CLOSE,M);

UB:BOLL+2*STD(CLOSE,M);
LB:BOLL-2*STD(CLOSE,M);

PBX1:(EMA(CLOSE,M1)+MA(CLOSE,M1*2)+MA(CLOSE,M1*4))/3;
PBX2:(EMA(CLOSE,M2)+MA(CLOSE,M2*2)+MA(CLOSE,M2*4))/3;
PBX3:(EMA(CLOSE,M3)+MA(CLOSE,M3*2)+MA(CLOSE,M3*4))/3;
PBX4:(EMA(CLOSE,M4)+MA(CLOSE,M4*2)+MA(CLOSE,M4*4))/3;
PBX5:(EMA(CLOSE,M5)+MA(CLOSE,M5*2)+MA(CLOSE,M5*4))/3;
PBX6:(EMA(CLOSE,M6)+MA(CLOSE,M6*2)+MA(CLOSE,M6*4))/3;

UPPER:(1+M1/100)*MA(CLOSE,N);
LOWER:(1-M2/100)*MA(CLOSE,N);
ENE:(UPPER+LOWER)/2;

HLC:=REF(MA((HIGH+LOW+CLOSE)/3,N),1);
HV:=EMA(HHV(HIGH,N),3);
LV:=EMA(LLV(LOW,N),3);
STOR:EMA(2*HV-LV,3);
MIDR:EMA(HLC+HV-LV,3);
WEKR:EMA(HLC*2-LV,3);
WEKS:EMA(HLC*2-HV,3);
MIDS:EMA(HLC-HV+LV,3);
STOS:EMA(2*LV-HV,3);

VAR2:=CLOSE*VOL;
VAR3:=EMA((EMA(VAR2,3)/EMA(VOL,3)+EMA(VAR2,6)/EMA(VOL,6)+EMA(VAR2,12)/EMA(VOL,12)+EMA(VAR2,24)/EMA(VOL,24))/4,N);
SUP:1.06*VAR3;
SDN:VAR3*0.94;
VAR4:=EMA(CLOSE,9);
LUP:EMA(VAR4*1.14,5);
LDN:EMA(VAR4*0.86,5);

AA:=MA((2*CLOSE+HIGH+LOW)/4,5); 
通道1:AA*N/100; 
通道2:AA*(200-N)/100; 
CC:=ABS((2*CLOSE+HIGH+LOW)/4-MA(CLOSE,20))/MA(CLOSE,20); 
DD:=DMA(CLOSE,CC); 
通道3:(1+M/100)*DD; 
通道4:(1-M/100)*DD;

【箱顶】:PEAK(CLOSE,N,1)*0.98;
【箱底】:TROUGH(CLOSE,N,1)*1.02;
【箱高】:100*(【箱顶】-【箱底】)/【箱底】,NODRAW;

AA:=ABS((2*CLOSE+HIGH+LOW)/4-MA(CLOSE,N))/MA(CLOSE,N);
济安线:DMA((2*CLOSE+LOW+HIGH)/4,AA),LINETHICK3,COLORMAGENTA;
CC:=(CLOSE/济安线);
MA1:=MA(CC*(2*CLOSE+HIGH+LOW)/4,3);
MAAA:=((MA1-济安线)/济安线)/3;
TMP:=MA1-MAAA*MA1;
